const test = require('node:test');
const assert = require('node:assert');
const { request } = require('../src/http');

function replies(...statuses) {
  const calls = [];
  const fetchImpl = async (url) => { calls.push(url); return { status: statuses[calls.length - 1], ok: statuses[calls.length - 1] < 400 }; };
  return { fetchImpl, calls };
}

test('a 503 is retried until it succeeds', async () => {
  const { fetchImpl, calls } = replies(503, 503, 200);
  const res = await request(fetchImpl, 'https://x.test/', { baseDelayMs: 0 });
  assert.strictEqual(res.status, 200);
  assert.strictEqual(calls.length, 3);
});

test('501 is not retried', async () => {
  const { fetchImpl, calls } = replies(501, 200);
  assert.strictEqual((await request(fetchImpl, 'https://x.test/', { baseDelayMs: 0 })).status, 501);
  assert.strictEqual(calls.length, 1);
});
# workerkit

Small HTTP client used by the workerkit workers.

request(fetch, url, options):

- timeoutMs: abort the request after this many milliseconds. Default 10000. 0 disables the timeout.
- retries: how many times to retry a 429 or 5xx response. Default 2. 501 Not Implemented is never retried, because it will not change on a retry.
- baseDelayMs: base of the backoff between retries. Default 250. Each wait uses full jitter: a random time between 0 and baseDelayMs * 2^attempt, capped at 8 seconds.
- init: passed to fetch as is.

The nightly export (src/export.js) sets timeoutMs: 0, because a full export can take ten minutes.
